type IsString<T> = T extends string ? true : false;

// Case A
type A = IsString<string | number>; 

// Case B
type IsStringStrict<T> = [T] extends [string] ? true : false;
type B = IsStringStrict<string | number>;

type Unpack<T> = T extends (infer U)[] 
  ? U 
  : T extends (...args: any[]) => infer R 
  ? R 
  : T;

type Res1 = Unpack<string[]>;
type Res2 = Unpack<() => number>;

type User = { name: string; age: number };

type CreateSetters<T> = {
  [K in keyof T as `set${Capitalize<string & K>}`]: (value: T[K]) => void
};

type UserSetters = CreateSetters<User>;

type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object ? DeepPartial<T[P]> : T[P];
};

type A = { x: number };
type B = { y: string };
type C = A & B;
// VS Code hover shows: type C = A & B

type ParseUrl<T> = T extends `${string}/:${infer Param}/${infer Rest}`
  ? Param | ParseUrl<`/${Rest}`>
  : T extends `${string}/:${infer Param}`
    ? Param
    : never;

type Result = ParseUrl<"/posts/:postId/comments/:commentId">;

type Original = {
  readonly id: number;
  name?: string;
};

type MutableRequired<T> = {
  -readonly [P in keyof T]-?: T[P];
};

type Result = MutableRequired<Original>;

type FilterNumber<T> = T extends number ? T : never;
type Values = string | number | boolean;

type Result = FilterNumber<Values>;

const config = {
  theme: "dark",
  retries: 5
} as const;

type Config = typeof config;
type Theme = Config["theme"];
